using Godot;
using System;
using System.Linq;
using System.Collections.Generic;
public partial class MigrationScene {
 readonly HashSet<ExpeditionGame> millParticipants=new();
 void StartMillFight(){if(dungeon!=null||NearProp(13,4)==null)return;if(game.World.Changes.MillDefeated){game.Notice="The Foreman is dead / this mill is cleared";return;}if(infected.Any(e=>IsMillBoss(e.Id))){game.Notice="The Foreman is already in the yard";return;}millParticipants.Clear();foreach(var pair in MillPlayers())if(InMill(pair.Body.Position.X,pair.Body.Position.Z,60))millParticipants.Add(pair.Game);AddEnemy(MillBossId,MillX,MillZ,2);game.Notice="THE FOREMAN / clear the warning zones / bait his charge into logs";}
 void AddMillBoss(string id,double x,double z){if(infected.Any(e=>e.Id==id)||game.World.Changes.MillDefeated)return;var body=new CharacterBody3D{Name="TheForeman",Position=new((float)x,(float)millFloor,(float)z),FloorSnapLength=.5f};body.AddChild(new CollisionShape3D{Position=new(0,2.25f,0),Shape=new CapsuleShape3D{Radius=1.1f,Height=4.5f}});var visual=new Node3D();body.AddChild(visual);ForemanModel(visual);AddChild(body);int players=CoopHost?MillPlayers().Count(p=>InMill(p.Body.Position.X,p.Body.Position.Z,60)):1;double hp=1400*(1+.5*Math.Max(0,players-1));infected.Add(new Infected{Id=id,Body=body,Visual=visual,Tier=2,Hp=hp,MaxHp=hp,Home=body.Position,Target=body.Position,BossState="hunt",BossTime=3});}
 void ForemanModel(Node3D root){HumanCharacter(root,2,2,false,6);root.Scale=new(2.1f,2.3f,2.1f);foreach(string side in new[]{"Left","Right"}){var arm=root.GetNode<Node3D>(side+"Arm");arm.Position=new(side=="Left"?-.43f:.43f,arm.Position.Y,arm.Position.Z);arm.Scale=new(1.35f,1,1.35f);}var torso=root.GetNode<Node3D>("Torso");torso.Scale=new(1.65f,1,1.45f);Ellipsoid(torso,new(0,.08f,-.10f),new(.34f,.34f,.28f),new(.45f,.47f,.29f));var throat=root.GetNode<Node3D>("Torso/Head");Ellipsoid(throat,new(0,-.04f,-.03f),new(.12f,.10f,.10f),new(.35f,.52f,.20f));for(int side=-1;side<=1;side+=2){Tube(torso,new(side*.23f,.37f,-.16f),new(side*.14f,-.18f,-.24f),.025f,new(.22f,.13f,.08f));Ellipsoid(torso,new(side*.20f,.03f,-.32f),new(.06f,.08f,.035f),new(.68f,.29f,.13f));}Bevel(throat,new(0,.26f,.005f),new(.24f,.07f,.21f),new(.63f,.44f,.17f));Box(torso,new(0,-.12f,-.35f),new(.30f,.30f,.045f),new(.33f,.16f,.10f));}
 System.Collections.Generic.List<(ExpeditionGame Game,CharacterBody3D Body)> MillPlayers(){var result=new System.Collections.Generic.List<(ExpeditionGame,CharacterBody3D)>();if(CoopHost){result.Add((coopHostGame,GetNode<CharacterBody3D>("Survivor")));result.AddRange(coopActors.Values.Select(a=>(a.Game,a.Body)));}else result.Add((game,player));return result;}
 void TickMillBoss(Infected boss,double dt){var candidates=MillPlayers().Where(p=>InMill(p.Body.Position.X,p.Body.Position.Z,42)&&p.Game.Life.Health>0).ToArray();if(candidates.Length==0){boss.Memory+=dt;if(boss.Memory>8){RemoveEnemy(boss);ClearMillPools();millParticipants.Clear();game.Notice="The Foreman recovered / ring the bell to try again";}return;}boss.Memory=0;var target=candidates.OrderBy(p=>Distance(p.Body.Position,boss.Body.Position)).First();boss.BossTime-=dt;bool angry=boss.Hp<boss.MaxHp*.5;Vector3 direction=target.Body.Position-boss.Body.Position;direction.Y=0;
  if(boss.BossState=="hunt"){
   if(direction.LengthSquared()>.1f)boss.Body.Rotation=new(0,Mathf.Atan2(-direction.X,-direction.Z),0);var velocity=direction.Length()>3?direction.Normalized()*(angry?1.9f:1.35f):Vector3.Zero;BossMove(boss,velocity,dt);if(boss.BossTime<=0){boss.BossStep++;boss.BossAim=target.Body.Position;boss.BossHits.Clear();boss.BossState=boss.BossStep%3==1?"slam":boss.BossStep%3==2?"retch":"charge-windup";boss.BossTime=(boss.BossState=="slam"?1.9:2.3)*(angry?.75:1);Sound(4);}return;
  }
  if(boss.BossState=="charge"){
   var rush=boss.BossAim-boss.Body.Position;rush.Y=0;if(rush.LengthSquared()>.01)rush=rush.Normalized();Vector3 before=boss.Body.Position;BossMove(boss,rush*13,dt);MillHitArea(boss,boss.Body.Position,2,24,true,true);bool wall=Enumerable.Range(0,boss.Body.GetSlideCollisionCount()).Any(i=>Math.Abs(boss.Body.GetSlideCollision(i).GetNormal().Y)<.4);if(wall||Distance(before,boss.Body.Position)<dt*3||!InMill(boss.Body.Position.X,boss.Body.Position.Z,30)){boss.Body.Position=before;boss.BossState="stunned";boss.BossTime=5;game.Notice="FOREMAN STUNNED / exposed belly!";}else if(boss.BossTime<=0){boss.BossState="recover";boss.BossTime=3;}return;
  }
  if(boss.BossTime>0)return;
  if(boss.BossState=="slam"){MillHitArea(boss,boss.Body.Position,6.5f,24,false,false);ImpactParticles(boss.Body.Position+Vector3.Up*.1f,new(.65f,.43f,.20f),24,.16f);boss.BossState="recover";boss.BossTime=3.5;}
  else if(boss.BossState=="retch"){CreateMillVomit(boss);boss.BossState="recover-vomit";boss.BossTime=3;}
  else if(boss.BossState=="charge-windup"){Vector3 aim=boss.BossAim-boss.Body.Position;aim.Y=0;boss.BossAim=boss.Body.Position+aim.Normalized()*22;boss.BossState="charge";boss.BossTime=1.7;}
  else{boss.BossState="hunt";boss.BossTime=angry?2:3;}
 }
 void BossMove(Infected boss,Vector3 velocity,double dt){velocity.Y=boss.Body.IsOnFloor()?-.2f:boss.Body.Velocity.Y-18*(float)dt;boss.Body.Velocity=velocity;boss.Body.MoveAndSlide();if(boss.Body.Position.Y<millFloor-1)boss.Body.Position=new(boss.Body.Position.X,(float)millFloor,boss.Body.Position.Z);}
 void MillHitArea(Infected boss,Vector3 origin,float radius,double damage,bool wound,bool once){foreach(var pair in MillPlayers()){if(Distance(pair.Body.Position,origin)>radius||once&&boss.BossHits.Contains(pair.Body.GetInstanceId()))continue;if(once)boss.BossHits.Add(pair.Body.GetInstanceId());MillDamage(pair.Game,pair.Body,damage,wound);}MillHurtCommunity(boss,origin,radius,damage,once);}
 void MillDamage(ExpeditionGame character,CharacterBody3D body,double damage,bool wound){if(character.Shield>0)return;character.Life.Health-=damage*100/(100+character.GearArmor+character.Talent("armor")*8)*(1-character.Talent("guard")*.05)*(character.Talent("resolve")>0&&character.Life.Health<character.MaxHealth*.3?.8:1);character.LastDamage=character.Clock;if(wound)character.Life.Wounds.Add(new ExpeditionWound());if(character.Life.Health>0)return;if(!CoopHost){Die();return;}character.Die(CampSafe);body.Position=Ground(character.Save.X,character.Save.Z)+Vector3.Up*.3f;body.Velocity=Vector3.Zero;var actor=coopActors.Values.FirstOrDefault(a=>a.Body==body);if(actor!=null)RpcId(actor.Id,nameof(CoopPersonal),CoopProfileJson(character),character.Notice,body.Position,true);}
 double MillDamageMultiplier(Infected boss,Vector3 point){bool weak=point.Y-boss.Body.Position.Y<3.1f&&point.Y-boss.Body.Position.Y>1.8f;return boss.BossState=="stunned"?2:boss.BossState.StartsWith("recover")?1.5:weak?1.15:1;}
 void DefeatMillBoss(Infected boss){var authority=CoopHost?coopHostGame:game;if(!authority.Change(()=>authority.World.Changes.MillDefeated=true)){boss.Hp=1;boss.BossState="stunned";boss.BossTime=5;return;}foreach(var pair in MillPlayers())if(InMill(pair.Body.Position.X,pair.Body.Position.Z,75))millParticipants.Add(pair.Game);foreach(var character in millParticipants){if(character.Craft.ResearchAwards.Contains("boss/foreman/reward"))continue;character.Change(()=>{character.AwardResearch("boss/foreman/reward",15);character.Career.Gain(300);character.Life.MillCores++;character.Life.Bandages+=4;character.Craft.Reserve+=72;character.Profile.Items.Add(new ExpeditionRelic{Id="boss/foreman/apron",Name="Foreman's reinforced apron",Origin="Ashen Lumber Mill",Slot="chest",Level=2,Armor=30,Vitality=12});});}BloodImpact(boss.Body.Position+Vector3.Up*2,Vector3.Up,45);DeathRemains(boss);RemoveEnemy(boss);ClearMillPools();game.Notice="FOREMAN DEFEATED / core, apron, ammunition and research awarded";authority.Persist();}
}
